'use strict';
const test=require('node:test'),a=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const M=require('../management'),I=require('../integration'),F=require('../contract'),C=require('../../dashboard2/calculations'),G=require('../goals'),T=require('../../growth/targets');
const shop=require('../staging/'+require('../staging/manifest').file),markets=require('../marketplaces/staging/'+require('../marketplaces/staging/manifest').file),raw=require('../../data.json'),legacy=require('../../dashboard2/sales-data.json').records;
const start='2025-08-01',end='2026-07-31',now=new Date('2026-10-14T12:00:00Z');
function records(basis,s=shop){const r=legacy.slice();r.management={shop:s,markets,basis};return r;}
function view(fy='FY26'){return {...raw.years[fy],fy,marketingYesterday:raw.yesterday};}
function sumMoney(values){return values.reduce((n,v)=>n+Math.round(v*100),0);}
test('Simple Net/Gross/Total selector has explicit native components and no scenario interface',()=>{a.deepEqual(I.BASIS,['net_revenue','gross_revenue','total_sales']);a.deepEqual(I.BASIS.map(b=>I.labels[b]),['Net Sales','Gross Sales','Total Sales']);a.equal(I.report(shop,start,end,'net_revenue').revenue,271670.54);a.equal(I.report(shop,start,end,'total_sales').revenue,313437.06);a.equal(I.report(shop,start,end,'gross_revenue').revenue,null);const html=fs.readFileSync(path.join(__dirname,'../../index.html'),'utf8');a.doesNotMatch(html,/RorPlanning|RorCostInputs|data-scenario-control|planning\/control|BREAK EVEN/);a.match(html,/fmtC\(selectedActual,2\)/);});
test('Net shipping and native source measures sum daily/monthly/FY identically in Growth and ROR',()=>{const before=JSON.stringify(shop);for(const basis of ['net_revenue','total_sales']){const v=I.growthView(view(),shop,basis,now),r=records(basis),opts={channels:['shopify'],startDate:start,endDate:end},agg=C.aggregate(r,opts),table=C.buildComparisonTable(r,{...opts,fromPeriod:start,toPeriod:end,granularity:'monthly',metric:'revenue'});a.equal(agg.revenue,v.summary.ytdRevenue);a.equal(table.totals.revenue,agg.revenue);a.equal(sumMoney(v.monthly.map(m=>m.revenue)),Math.round(agg.revenue*100));a.equal(v.monthly.reduce((n,m)=>n+m.orders,0),7832);a.equal(agg.aov,agg.revenue/7832);const days=shop.days.filter(d=>d.day>=start&&d.day<=end);a.equal(days.reduce((n,d)=>n+M.shopify(shop,d.day,d.day,basis).value,0),Math.round(agg.revenue*100));}a.equal(JSON.stringify(shop),before);});
test('Gross shipping unavailable never substitutes merchandise gross or changes eligible orders',()=>{const r=C.aggregate(records('gross_revenue'),{channels:['shopify'],startDate:start,endDate:end});a.equal(r.revenue,null);a.equal(r.orders,7832);a.equal(I.growthView(view(),shop,'gross_revenue',now).summary.ytdRevenue,null);});
test('Actual private native gross-shipping capture reconciles all approved FY26 source amounts',{skip:!process.env.PRIVATE_GROSS_SHIPPING_CANDIDATE},()=>{const s=JSON.parse(fs.readFileSync(process.env.PRIVATE_GROSS_SHIPPING_CANDIDATE));a.equal(M.shopify(s,start,end,'gross_revenue').value,30010551);a.equal(F.select(s,start,end).gross_shipping_charges,2388450);require('../publication').validate(s);for(const b of I.BASIS){const v=I.growthView(view(),s,b,now),agg=C.aggregate(records(b,s),{channels:['shopify'],startDate:start,endDate:end});a.equal(v.summary.ytdRevenue,agg.revenue);a.equal(sumMoney(v.monthly.map(m=>m.revenue)),Math.round(agg.revenue*100));}for(const d of s.days){const old=shop.days.find(x=>x.day===d.day);for(const k of F.ADDITIVE)a.equal(d[k],old[k]);}});
test('Marketplace management estimates stay provisional; current gaps never become legacy gross',()=>{const r=M.select(shop,markets,['shopify','etsy','noths'],start,end,'net_revenue');a.equal(r.value,39813918);a.equal(r.confidence,'provisional');a.equal(r.parts.find(p=>p.channel==='etsy').value,2574484);a.equal(r.parts.find(p=>p.channel==='noths').value,10072380);a.equal(r.parts.find(p=>p.channel==='noths').orders,3786);a.equal(M.marketplace(markets,'etsy',start,end,'net_sales').value,3038999);a.equal(M.select(shop,markets,['shopify','etsy','noths'],'2026-08-01','2026-10-13','net_revenue').value,null);a.equal(M.select(shop,markets,['etsy'],'2026-10-01','2026-10-13','net_revenue').value,null);const old=C.aggregate(records('legacy_gross'),{channels:['shopify','etsy','noths'],startDate:start,endDate:end});a.equal(Math.round(old.revenue*100),46695548);a.equal(old.orders,12680);});
test('Approved goals and model Net Sales remain independent of selected actual and local exploration',()=>{a.equal(G.annual('FY27'),300000);a.equal(G.annual('FY27','all'),500000);a.equal(G.basis,'net_revenue');a.equal(T.allocate(G.annual('FY27')).reduce((n,x)=>n+Math.round(x*100),0),30000000);a.equal(T.plan(500000,'FY27','2026-10-11').ytdTarget,84526.22);const net=I.growthView(view(),shop,G.basis,now);a.equal(net.summary.basisAov,271670.54/7832);I.growthView(view(),shop,'total_sales',now);a.equal(G.annual('FY27'),300000);});
test('Product-only costed margin, profit and existing LTV methodology remain untouched across sales bases',()=>{for(const b of I.BASIS){const v=I.growthView(view(),shop,b,now);a.equal(v.summary.ytdEstGrossProfit,raw.years.FY26.summary.ytdEstGrossProfit);for(const m of v.monthly){const old=raw.years.FY26.monthly.find(r=>r.key===m.key);for(const k of ['costOfGoodsSold','marginPctCovered','estGrossProfit','costCoverage'])a.equal(m[k],old[k]);}}const html=fs.readFileSync(path.join(__dirname,'../../index.html'),'utf8');a.match(html,/const yProfitTarget  = null/);a.match(html,/period|proxy/);});
// Hash of the complete production CSS block, including every desktop/mobile media rule.
test('Production typography, colours, spacing and responsive CSS remain byte-identical',()=>{const html=fs.readFileSync(path.join(__dirname,'../../index.html'),'utf8'),css=/<style>([\s\S]*?)<\/style>/.exec(html)[1];a.equal(crypto.createHash('sha256').update(css).digest('hex'),process.env.FOUNDATION_CSS_HASH||'25ea1ef39c8496636ed65a57b175b3891a80a683ad3d99aeee4c54cc0e41d24b');});
test('Every original date preset and custom interval keeps selected shipping-inclusive money/counts consistent',()=>{const s=process.env.PRIVATE_GROSS_SHIPPING_CANDIDATE?JSON.parse(fs.readFileSync(process.env.PRIVATE_GROSS_SHIPPING_CANDIDATE)):shop;for(const basis of I.BASIS)for(const preset of C.REPORT_DATE_PRESETS){const r=C.resolveDateRange(preset.key,{nowDate:now,customStart:'2026-08-10',customEnd:'2026-09-15',availableStart:s.coverage.start,availableEnd:s.coverage.end});if(r.unsupported)continue;const opts={channels:['shopify'],startDate:r.startDate,endDate:r.endDate},agg=C.aggregate(records(basis,s),opts),native=I.report(s,r.startDate,r.endDate,basis);a.equal(agg.revenue,native.revenue,preset.key+' '+basis);a.equal(agg.orders,native.orders);if(agg.revenue!=null)a.equal(agg.aov,agg.revenue/agg.orders);}});
